syntax:
if (condition)          // condition goes inside brackets, NO semicolon here
{
    statement1;         // runs only when the condition is true
    statement2;
}
nextStatement;          // always runs, true or false

// With one statement the braces are optional:
if (condition)
    statement;          // only THIS line belongs to the if

sample.code:
#include <iostream>
using namespace std;

int main() {
    int temperature = 38;
    if (temperature > 35) {
        cout << "It's a hot day!" << endl;
    }
    cout << "Program finished." << endl;
    return 0;
}

#include <iostream>
using namespace std;

int main() {
    int marks;
    cout << "Enter marks: ";
    cin >> marks;
    if (marks >= 50) {
        cout << "Congratulations, you passed!" << endl;
    }
    cout << "Program finished." << endl;
    return 0;
}

#include <iostream>
using namespace std;

int main() {
    int total;
    cout << "Enter total: ";
    cin >> total;
    if (total >= 5000) {
        int discount = total / 10;
        total = total - discount;
    }
    cout << "Amount to pay: " << total << endl;
    return 0;
}

